    "code": "package kh.gov.esb.application.modules.health_supporting_product.strategy;\n\nimport kh.gov.esb.application.avro.farm.ApplicationApprovedMessage;\nimport kh.gov.esb.application.exception.CustomValidationException;\nimport kh.gov.esb.application.modules.application.dto.ApplicationRequestServiceDto;\nimport kh.gov.esb.application.modules.application.dto.response.base.BaseApplicationResponseDto;\nimport kh.gov.esb.application.modules.application.dto.response.base.BaseSlimApplicationResponseDto;\nimport kh.gov.esb.application.modules.application.model.application.Application;\nimport kh.gov.esb.application.modules.application.strategy.application.ApplicationStrategy;\nimport kh.gov.esb.application.modules.application.strategy.application.ApplicationStrategyAction;\nimport kh.gov.esb.application.modules.application.strategy.handler.ApplicationCoreHandler;\nimport kh.gov.esb.application.modules.health_supporting_product.builder.HealthSupportingOperationCertificateBuilder;\nimport kh.gov.esb.application.modules.health_supporting_product.dto.HealthSupportingOperationRequestDto.Product;\nimport kh.gov.esb.application.modules.health_supporting_product.dto.HealthSupportingOperationRequestDto;\nimport kh.gov.esb.application.modules.health_supporting_product.dto.HealthSupportingRenewalRequestDto;\nimport kh.gov.esb.application.modules.health_supporting_product.service.HealthSupportingProductDraftService;\nimport kh.gov.esb.common_library.exception.BaseException;\nimport lombok.RequiredArgsConstructor;\nimport org.springframework.transaction.annotation.Transactional;\nimport java.util.HashSet;\nimport java.util.LinkedHashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Set;\n\n@RequiredArgsConstructor\npublic class HealthSupportingRenewalApplicationStrategy implements ApplicationStrategy<HealthSupportingOperationRequestDto> {\n    private final ApplicationCoreHandler core;\n    private final HealthSupportingProductDraftService drafts;\n    private final HealthSupportingOperationCertificateBuilder certificateBuilder;\n\n    @Override\n    @Transactional(rollbackFor = Exception.class)\n    public Application saveApplication(Long id, HealthSupportingOperationRequestDto request, Application existing) throws BaseException {\n        Application previous = id == null ? null : existing != null ? existing : core.getApplicationById(id);\n        drafts.preserveOmittedFields(request, previous);\n        if (request.getProducts() != null) for (Product product : request.getProducts()) validateProduct(product, false);\n        Application saved = drafts.saveApplication(id, request, previous, \"GDHT-HS-R\", \"Renewal\", true);\n        if (request instanceof HealthSupportingRenewalRequestDto renewal && renewal.getEstablishmentDecisionOutdated() != null) {\n            Map<String,Object> metadata = new LinkedHashMap<>(saved.getMetadata() == null ? Map.of() : saved.getMetadata());\n            metadata.put(\"dr09_establishment_decision_outdated\", renewal.getEstablishmentDecisionOutdated());\n            saved.setMetadata(metadata);\n        }\n        return saved;\n    }\n    @Override\n    public Application submitApplication(Long id) throws BaseException {\n        Application app = core.getApplicationById(id);\n        return core.submitApplication(id, (request, errors) -> validateStored(app, errors));\n    }\n    @Override\n    public void validateSubmitApplication(Application app) throws BaseException {\n        core.validateSubmitApplication(app, (request, errors) -> validateStored(app, errors));\n    }\n    private void validateStored(Application app, Map<String, Object> errors) {\n        drafts.validateSnapshots(app, true, errors);\n        Object outdated = app.getMetadata() == null ? null : app.getMetadata().get(\"dr09_establishment_decision_outdated\");\n        if (!(outdated instanceof Boolean)) errors.put(\"establishment_decision_outdated\", \"required\");\n        else if (Boolean.TRUE.equals(outdated) && (app.getAttachments() == null || app.getAttachments().stream()\n                .noneMatch(file -> \"establishment_decision\".equals(file.getKey()) && file.getId() != null && !file.getId().isBlank()\n                        && !(app.getMetadata().get(\"dr09_source_establishment_decision_ids\") instanceof List<?> previousIds && previousIds.contains(file.getId()))))) {\n            errors.put(\"attachments.establishment_decision\", \"required.when.outdated\");\n        }\n        List<Product> products = drafts.products(app);\n        for (int index = 0; index < products.size(); index++) {\n            Product product = products.get(index);\n            try {\n                validateProduct(product, true);\n\n            } catch (BaseException error) { drafts.addProductErrors(errors, index, product.getLicenseId(), error); }\n        }\n    }\n    void validateProduct(Product product, boolean submitting) throws BaseException {\n        drafts.validateTarget(product);\n        if (product.getChanges() != null && !product.getChanges().isEmpty()) throw invalid(\"products.changes\", \"Renewal does not edit product facts\");\n        Set<String> required = new HashSet<>(Set.of(\"coa\", \"free_sale_certificate\", \"letter_of_authorization\", \"application_form\"));\n        if (product.getChangedDocuments() != null) {\n            if (!Set.of(\"smpc_product_information\", \"technical_documents\", \"product_photo\").containsAll(product.getChangedDocuments())) throw invalid(\"products.changedDocuments\", \"Invalid renewal evidence selection\");\n            required.addAll(product.getChangedDocuments());\n        }\n        if (submitting) drafts.requireDocuments(product, required);\n    }\n    @Override\n    public List<ApplicationRequestServiceDto> getApplicationRequestServices(Application app) throws BaseException {\n        List<Product> products = drafts.products(app);\n        if (products.isEmpty()) throw invalid(\"products\", \"DR09 product selection required\");\n        for (Product product : products) validateProduct(product, false);\n        return List.of(ApplicationRequestServiceDto.builder().serviceCode(\"GDHT-HS-R\").quantity(products.size()).build());\n    }\n    @Override\n    public BaseApplicationResponseDto mapToResponseDto(Application app) { return drafts.mapToResponseDto(app); }\n    @Override\n    public BaseSlimApplicationResponseDto mapToSlimResponseDto(Application app) { return drafts.mapToSlimResponseDto(app); }\n    @Override\n    public Map<String, Object> buildApprovedFormData(Application app) { return drafts.buildApprovedFormData(app); }\n    @Override\n    public ApplicationApprovedMessage toApplicationApprovedMessage(Application app, String form) { return drafts.toApplicationApprovedMessage(app, form); }\n    @Override\n    public void sendNotifications(Application app, ApplicationStrategyAction action) { core.sendNotifications(app, action); }\n    @Override\n    public List<Map<String, Object>> buildCertificateDataList(Application app) throws BaseException { return certificateBuilder.buildAll(app); }\n    @Override\n    public Map<String, Object> buildCertificateData(Application app) throws BaseException {\n        List<Map<String, Object>> results = buildCertificateDataList(app);\n        if (results.isEmpty()) throw invalid(\"products\", \"DR09 product selection required\");\n        return results.getFirst();\n    }\n    private static CustomValidationException invalid(String field, String message) { return new CustomValidationException(\"application.validation.failed\", Map.of(field, message)); }\n}"
