    "line": 1,
    "code": "package kh.gov.esb.application.modules.health_supporting_product.service;\n\nimport com.fasterxml.jackson.databind.DeserializationFeature;\nimport com.fasterxml.jackson.databind.JsonNode;\nimport com.fasterxml.jackson.databind.ObjectMapper;\nimport kh.gov.esb.application.constant.LicenseeType;\nimport kh.gov.esb.application.exception.CustomValidationException;\nimport kh.gov.esb.application.modules.applicant.dto.ApplicantRequestDto;\nimport kh.gov.esb.application.modules.applicant.mapper.ApplicantMapper;\nimport kh.gov.esb.application.modules.application.model.application.Application;\nimport kh.gov.esb.application.modules.company.dto.CompanyRequestDto;\nimport kh.gov.esb.application.modules.company.mapper.CompanyMapper;\nimport kh.gov.esb.application.modules.person.dto.PersonRequestDto;\nimport kh.gov.esb.application.modules.person.mapper.PersonMapper;\nimport lombok.RequiredArgsConstructor;\nimport org.springframework.stereotype.Component;\nimport java.util.Map;\n\n/** Copy parties from an already authorized licence-scoped Profile response; never accept client party replacements. */\n@Component\n@RequiredArgsConstructor\npublic class HealthSupportingPartyMapper {\n    private final ObjectMapper objectMapper;\n    private final ApplicantMapper applicantMapper;\n    private final CompanyMapper companyMapper;\n    private final PersonMapper personMapper;\n\n    public void fillMissingParties(JsonNode profile, Application target) {\n        if (profile == null || !profile.isObject()) return;\n        boolean empty = target.getApplicant() == null && target.getCompany() == null && target.getLicensee() == null;\n        ObjectMapper reader = objectMapper.copy().disable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES);\n        try {\n            if (target.getApplicant() == null && profile.path(\"applicant\").isObject()) {\n                target.setApplicant(applicantMapper.fromApplicantDto(reader.convertValue(profile.get(\"applicant\"), ApplicantRequestDto.class)));\n            }\n            if (target.getCompany() == null && profile.path(\"company\").isObject()) {\n                target.setCompany(companyMapper.fromCompanyRequestDto(reader.convertValue(profile.get(\"company\"), CompanyRequestDto.class)));\n            }\n            if (target.getLicensee() == null && profile.path(\"licensee\").isObject()) {\n                target.setLicensee(personMapper.toPerson(reader.convertValue(profile.get(\"licensee\"), PersonRequestDto.class)));\n            }\n            if (empty && profile.hasNonNull(\"licensee_type\")) target.setLicenseeType(LicenseeType.valueOf(profile.path(\"licensee_type\").asText()));\n        } catch (IllegalArgumentException error) {\n            throw new CustomValidationException(\"application.validation.failed\", Map.of(\"profile.parties\", \"source.party.data.invalid\"));\n        }\n    }\n}"
