    "code": "package kh.gov.esb.profile.modules.healthsupporting.strategy.handler;\n\nimport kh.gov.esb.application.avro.farm.ApplicationApprovedMessage;\nimport kh.gov.esb.common_library.enumeration.CommonErrorCode;\nimport kh.gov.esb.common_library.exception.BaseException;\nimport kh.gov.esb.profile.common.dto.ServiceDto;\nimport kh.gov.esb.profile.constant.LicenseOperationType;\nimport kh.gov.esb.profile.modules.core.license.dto.context.LicenseBuildContext;\nimport kh.gov.esb.profile.modules.core.license.model.License;\nimport kh.gov.esb.profile.modules.core.registration.model.RegulatoryRegistration;\nimport kh.gov.esb.profile.modules.healthsupporting.dto.HealthSupportingCertificateType;\nimport kh.gov.esb.profile.modules.healthsupporting.dto.operation.HealthSupportingOperationForm;\nimport kh.gov.esb.profile.modules.healthsupporting.dto.operation.HealthSupportingRegisterRequestDto;\nimport kh.gov.esb.profile.modules.healthsupporting.mapper.HealthSupportingMapper;\nimport kh.gov.esb.profile.modules.healthsupporting.strategy.builder.HealthSupportingLicenseBuilder;\nimport lombok.RequiredArgsConstructor;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\nimport java.time.Instant;\n\n@Service\n@RequiredArgsConstructor\npublic class HealthSupportingRenewalHandler {\n    private final HealthSupportingApprovalSupport approvals;\n    private final HealthSupportingMapper mapper;\n    private final HealthSupportingLicenseBuilder licenseBuilder;\n\n    @Transactional(rollbackFor = Exception.class)\n    public void handle(ApplicationApprovedMessage message) throws BaseException {\n        HealthSupportingApprovalSupport.ApprovalBatch batch = approvals.begin(message, \"GDHT-HS-R\", \"RENEW\");\n        if (batch == null) return;\n        for (int i = 0; i < batch.registrations().size(); i++) {\n            License license = batch.registrations().get(i).getLicense();\n            if (license.getStatus() == null || !license.getStatus().isRenewable()) throw invalid(\"DR09 licence not eligible\");\n            if (batch.details().get(i).getApplicationType() == null || license.getExpiryDate() == null\n                    || license.getMaxRenewableCount() != null\n                    && (license.getRenewedCount() == null ? 0 : license.getRenewedCount()) >= license.getMaxRenewableCount()) throw invalid(\"DR09 renewal limit reached\");\n            HealthSupportingOperationForm.Product product = batch.form().getProducts().get(i);\n            if (product.getChanges() != null && !product.getChanges().isEmpty()) throw invalid(\"Renewal cannot edit product fields\");\n        }\n        for (int i = 0; i < batch.registrations().size(); i++) {\n            RegulatoryRegistration registration = batch.registrations().get(i);\n            HealthSupportingRegisterRequestDto request = new HealthSupportingRegisterRequestDto();\n            request.setApplicationId(message.getId());\n            request.setApplicationNo(message.getApplicationNo());\n            request.setApplicationSubmittedDate(message.getCreatedDate() == null ? null : Instant.parse(message.getCreatedDate()));\n            request.setApplicationFirstSubmittedDate(request.getApplicationSubmittedDate());\n            request.setUserId(message.getUserId());\n            request.setDepartmentId(message.getDepartmentId());\n            request.setProfileId(batch.profile().getId());\n            request.setApprovedDate(message.getApprovedDate());\n            ServiceDto service = new ServiceDto();\n            service.setCode(message.getService().getCode());\n            request.setService(service);\n            request.setHealthSupportingProduct(mapper.toProductDto(batch.details().get(i)));\n            licenseBuilder.extend(registration, LicenseBuildContext.<HealthSupportingRegisterRequestDto, HealthSupportingCertificateType>builder()\n                    .requestDto(request).profile(batch.profile()).item(HealthSupportingCertificateType.HEALTH_SUPPORTING_PRODUCT_LICENSE)\n                    .operationType(LicenseOperationType.RENEW).build());\n            // Preserve the profile's original approval date; this licence is issued at the renewal approval date.\n            registration.getLicense().setIssueDate(batch.approvedAt());\n        }\n        approvals.complete(message, batch, LicenseOperationType.RENEW);\n    }\n    private static BaseException invalid(String message) { return new BaseException(message, CommonErrorCode.BAD_REQUEST.getValue(), HttpStatus.UNPROCESSABLE_ENTITY.value()); }\n}"
