    "code": "package kh.gov.esb.profile.modules.healthsupporting.strategy.handler;\n\nimport kh.gov.esb.application.avro.farm.ApplicationApprovedMessage;\nimport kh.gov.esb.common_library.enumeration.CommonErrorCode;\nimport kh.gov.esb.common_library.exception.BaseException;\nimport kh.gov.esb.profile.constant.LicenseOperationType;\nimport kh.gov.esb.profile.constant.LicenseStatus;\nimport kh.gov.esb.profile.modules.healthsupporting.dto.operation.HealthSupportingOperationForm;\nimport kh.gov.esb.profile.modules.healthsupporting.model.HealthSupportingProductLicenseDetail;\nimport lombok.RequiredArgsConstructor;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\nimport java.util.HashSet;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Objects;\nimport java.util.Set;\n\n@Service\n@RequiredArgsConstructor\npublic class HealthSupportingUpdateHandler {\n    private final HealthSupportingApprovalSupport approvals;\n\n    @Transactional(rollbackFor = Exception.class)\n    public void handle(ApplicationApprovedMessage message) throws BaseException {\n        HealthSupportingApprovalSupport.ApprovalBatch batch = approvals.begin(message, \"GDHT-HS-U\", \"UPDATE\");\n        if (batch == null) return;\n        for (int i = 0; i < batch.registrations().size(); i++) {\n            if (batch.registrations().get(i).getLicense().getStatus() != LicenseStatus.ACTIVE) throw invalid(\"DR09 licence not eligible\");\n            HealthSupportingOperationForm.Product product = batch.form().getProducts().get(i);\n            validateChanges(product);\n            for (HealthSupportingOperationForm.Change change : product.getChanges()) {\n                if (change.getValues().entrySet().stream().allMatch(field -> Objects.equals(field.getValue(), product.getSourceProduct().path(field.getKey()).asText(null)))) throw invalid(\"DR09 variation does not change any value\");\n            }\n        }\n        for (int i = 0; i < batch.details().size(); i++) {\n            for (HealthSupportingOperationForm.Change change : batch.form().getProducts().get(i).getChanges()) apply(batch.details().get(i), change.getValues());\n        }\n        approvals.complete(message, batch, LicenseOperationType.REGENERATE);\n    }\n    private static final Map<String, Set<String>> FIELDS = Map.of(\n            \"GDHT-HS-UPN\", Set.of(\"product_name\"), \"GDHT-HS-UP\", Set.of(\"pack_size\"),\n            \"GDHT-HS-UM\", Set.of(\"mah_name\", \"mah_address\"),\n            \"GDHT-HS-UMF\", Set.of(\"manufacturer_name\", \"manufacturer_address\"));\n    static void validateChanges(HealthSupportingOperationForm.Product product) throws BaseException {\n        List<HealthSupportingOperationForm.Change> changes = product.getChanges() == null ? List.of() : product.getChanges();\n        if (changes.isEmpty()) throw invalid(\"DR09 variation requires a change\");\n        Set<String> seen = new HashSet<>();\n        for (HealthSupportingOperationForm.Change change : changes) {\n            if (change == null || !seen.add(change.getServiceCode()) || !FIELDS.containsKey(change.getServiceCode())\n                    || change.getValues() == null || change.getValues().isEmpty()\n                    || !FIELDS.get(change.getServiceCode()).containsAll(change.getValues().keySet())) throw invalid(\"Invalid DR09 change scope\");\n            for (Map.Entry<String, String> field : change.getValues().entrySet()) {\n                if (field.getValue() == null || field.getValue().isBlank() || field.getValue().length() > (field.getKey().endsWith(\"address\") ? 1000 : 255)) throw invalid(\"Invalid DR09 change value\");\n            }\n        }\n    }\n\n    private void apply(HealthSupportingProductLicenseDetail detail, Map<String, String> values) {\n        values.forEach((key, value) -> {\n            switch (key) {\n                case \"product_name\" -> detail.setProductName(value);\n                case \"pack_size\" -> detail.setPackSize(value);\n                case \"mah_name\" -> detail.setMahName(value);\n                case \"mah_address\" -> detail.setMahAddress(value);\n                case \"manufacturer_name\" -> detail.setManufacturerName(value);\n                case \"manufacturer_address\" -> detail.setManufacturerAddress(value);\n                default -> throw new IllegalArgumentException(\"Unsupported DR09 product field\");\n            }\n        });\n    }\n\n    private static BaseException invalid(String message) { return new BaseException(message, CommonErrorCode.BAD_REQUEST.getValue(), HttpStatus.UNPROCESSABLE_ENTITY.value()); }\n}"
