    "line": 1,
    "code": "package kh.gov.esb.profile.modules.healthsupporting.strategy.builder;\n\nimport kh.gov.esb.profile.constant.LicenseEntityType;\nimport kh.gov.esb.profile.constant.ResourceType;\nimport kh.gov.esb.profile.modules.core.license.builder.BaseLicenseBuilder;\nimport kh.gov.esb.profile.modules.core.license.dto.context.LicenseBuildContext;\nimport kh.gov.esb.profile.modules.core.license.model.License;\nimport kh.gov.esb.profile.modules.core.registration.model.RegulatoryRegistration;\nimport kh.gov.esb.profile.modules.core.sequence.SequenceFormat;\nimport kh.gov.esb.profile.modules.core.sequence.SequenceService;\nimport kh.gov.esb.profile.modules.core.service.Service;\nimport kh.gov.esb.profile.modules.core.service.ServiceCatalog;\nimport kh.gov.esb.profile.modules.healthsupporting.dto.HealthSupportingCertificateType;\nimport kh.gov.esb.profile.modules.healthsupporting.dto.operation.HealthSupportingRegisterRequestDto;\nimport lombok.RequiredArgsConstructor;\nimport org.springframework.stereotype.Component;\n\nimport java.time.LocalDate;\n\n@Component\n@RequiredArgsConstructor\npublic class HealthSupportingLicenseBuilder extends BaseLicenseBuilder<\n        HealthSupportingRegisterRequestDto, HealthSupportingCertificateType> {\n\n    /** Fallback only; the synced service-catalog row's validity_years (3) wins. */\n    private static final int VALIDITY_YEARS = 3;\n\n    private final SequenceService sequenceService;\n    private final ServiceCatalog serviceCatalog;\n\n    @Override\n    protected void applyServiceFields(RegulatoryRegistration registration,\n                                      LicenseBuildContext<HealthSupportingRegisterRequestDto,\n                                              HealthSupportingCertificateType> ctx) {\n        super.applyServiceFields(registration, ctx);\n        registration.setResourceType(ResourceType.HEALTH_SUPPORTING_PRODUCT);\n        registration.setEntityId(ctx.getProfile().getId() != null ? ctx.getProfile().getId().toString() : null);\n        registration.setEntityType(LicenseEntityType.HEALTH_SUPPORTING_PRODUCT.name());\n        registration.getLicense().setCertificateType(ctx.getItem().name());\n    }\n\n    @Override\n    protected String generateLicenseNo(License license,\n                                       LicenseBuildContext<HealthSupportingRegisterRequestDto,\n                                               HealthSupportingCertificateType> ctx) {\n        LocalDate now = LocalDate.now();\n        String date = String.format(\"%02d%02d\", now.getMonthValue(), now.getYear() % 100);\n        String seq = sequenceService.next(\"MOH/HEALTH-SUPPORTING-PRODUCT-LICENSE/\" + date, SequenceFormat.ofLength(4));\n        return String.format(\"MOH-HS/%s/%s\", seq, date);\n    }\n\n    @Override\n    protected String generateLicenseReferenceNo(\n            LicenseBuildContext<HealthSupportingRegisterRequestDto, HealthSupportingCertificateType> ctx) {\n        String seq = sequenceService.next(\"MOH/HEALTH-SUPPORTING-PRODUCT-LICENSE-REF\", SequenceFormat.ofLength(4));\n        LocalDate now = LocalDate.now();\n        return String.format(\"%s/%02d/%02d\", seq, now.getMonthValue(), now.getYear() % 100);\n    }\n\n    @Override\n    protected int validityYears(LicenseBuildContext<HealthSupportingRegisterRequestDto,\n            HealthSupportingCertificateType> ctx) {\n        return catalogService(serviceCatalog, ctx)\n                .map(Service::getValidityYears)\n                .orElse(VALIDITY_YEARS);\n    }\n\n    @Override\n    protected Integer maxRenewableCount(LicenseBuildContext<HealthSupportingRegisterRequestDto,\n            HealthSupportingCertificateType> ctx) {\n        return catalogService(serviceCatalog, ctx)\n                .map(Service::getMaxRenewableCount)\n                .orElse(null);\n    }\n}"
