    "code": "package kh.gov.esb.profile.modules.healthsupporting.dto.operation;\n\nimport com.fasterxml.jackson.annotation.JsonIgnoreProperties;\nimport com.fasterxml.jackson.databind.JsonNode;\nimport com.fasterxml.jackson.databind.PropertyNamingStrategies;\nimport com.fasterxml.jackson.databind.annotation.JsonNaming;\nimport kh.gov.esb.profile.common.model.Attachment;\nimport lombok.Data;\nimport java.time.Instant;\nimport java.util.List;\nimport java.util.Map;\n\n@Data\n@JsonIgnoreProperties(ignoreUnknown = true)\n@JsonNaming(PropertyNamingStrategies.SnakeCaseStrategy.class)\npublic class HealthSupportingOperationForm {\n    private Integer contractVersion;\n    private Boolean establishmentDecisionOutdated;\n    private Long profileId;\n    private List<Product> products;\n    private List<Attachment> attachments;\n\n    @Data\n    @JsonIgnoreProperties(ignoreUnknown = true)\n    @JsonNaming(PropertyNamingStrategies.SnakeCaseStrategy.class)\n    public static class Product {\n        private Long licenseId;\n        private Instant sourceExpiryDate;\n        private JsonNode sourceProduct;\n        private JsonNode sourceLicense;\n        private List<Change> changes;\n        private String cancellationReason;\n        private List<Attachment> attachments;\n    }\n\n    @Data\n    @JsonNaming(PropertyNamingStrategies.SnakeCaseStrategy.class)\n    public static class Change {\n        private String serviceCode;\n        private Map<String, String> values;\n    }\n}"
